(()=>{window.__bg = window.__bg || {};
window.__bgRows = function () { return JSON.parse(sessionStorage.getItem('moke_dataset')); };
window.__bgCol = function (name) { const d = __bgRows(); const i = d.headers.indexOf(name); return d.rows.map(r => r[i]); };
window.__bgNums = function (name) { return __bgCol(name).map(v => parseFloat(String(v))).filter(n => !isNaN(n)); };
window.__bgFmt = function (n) { return n.toLocaleString(undefined, { maximumFractionDigits: 2 }); };
window.__bgCard = function (id) { return document.getElementById('dc-' + id); };
window.__bgRun = async function (fn, promptId, text) {
  const real = window.fetch, RC = window.Chart, calls = [], charts = [];
  window.fetch = async function (u, o) {
    const r = await real(u, o);
    if (String(u).indexOf('/api/pipeline') >= 0) calls.push({ req: JSON.parse(o.body), status: r.status, res: await r.clone().text() });
    return r;
  };
  window.Chart = function (cv, cfg) { charts.push({ id: cv.id, labels: cfg.data.labels, data: cfg.data.datasets.map(d => d.data) }); this.destroy = function () {}; };
  try { document.getElementById(promptId).value = text; await window[fn](); }
  finally { window.fetch = real; window.Chart = RC; }
  return { calls, charts };
